"""Creator 6.8 candidate-generation brief with post-freeze agent synthesis."""
from __future__ import annotations
import json, subprocess, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PREFLIGHT=ROOT/'data/live/editorial_preflight.json'; NEWS=ROOT/'data/live/news_snapshot.json'; CONTEXT=ROOT/'data/live/publication_context.json'; CORE=ROOT/'data/live/superhuman_creator_core.json'; NOTES=ROOT/'docs/BINANCE_SQUARE_TOP_CREATOR_DEEP_RESEARCH_NOTES.md'; RESEARCH=ROOT/'data/live/original_research.json'; STRATEGY=ROOT/'data/live/agent_strategy.json'
def load(p):
    try:
        x=json.loads(p.read_text(encoding='utf-8'));return x if isinstance(x,dict) else {}
    except Exception:return {}
def run_script(name):
    proc=subprocess.run([sys.executable,str(ROOT/'src'/name)],capture_output=True,text=True)
    if proc.stdout:print(proc.stdout,end='')
    if proc.stderr:print(proc.stderr,end='',file=sys.stderr)
    if proc.returncode:raise SystemExit(proc.returncode)
def refresh_research():run_script('original_research_engine.py')
def main():
    refresh_research(); run_script('creator_agent_supervisor.py'); run_script('agent_strategy_bridge.py')
    p=load(PREFLIGHT); d=p.get('content_director_4') or {}; s=p.get('script_director_4') or {}; news=load(NEWS); ctx=load(CONTEXT); core=load(CORE); research=load(RESEARCH); strategy=load(STRATEGY)
    fmt=str(d.get('recommended_format') or 'TOP MOVERS'); sym=str(ctx.get('symbol') or s.get('primary_symbol') or (d.get('primary_story') or {}).get('symbol','')).upper().replace('USDT','').replace('$','').strip(); selected=p.get('selected_opportunity') or {}; story=d.get('primary_story') or {}; narrative=str(d.get('narrative_engine') or s.get('narrative_engine') or 'what_to_watch'); archetype=str(d.get('agent_archetype') or s.get('creator_archetype') or 'conversational'); hooks=s.get('hook_candidates') or []
    if not sym:raise SystemExit('Candidate generation: authoritative asset missing')
    if str(strategy.get('symbol') or '').upper().replace('USDT','')!=sym:raise SystemExit('Candidate generation: supervisor strategy asset does not match authoritative publication context')
    news_context=[{'title':a.get('title'),'source':a.get('source'),'url':a.get('url'),'published_at':a.get('published_at'),'summary':str(a.get('summary') or '')[:500],'symbols':a.get('symbols') or [],'news_score':a.get('news_score')} for a in (news.get('articles') or [])[:12] if isinstance(a,dict)]
    directives='\n'.join('- '+str(x) for x in (core.get('generation_directives') or [])); redteam='\n'.join('- '+str(x) for x in (core.get('red_team_questions') or [])); standard=json.dumps(core.get('minimum_publish_standard') or {},ensure_ascii=False)
    try:research_notes=NOTES.read_text(encoding='utf-8')[:24000]
    except Exception:research_notes=''
    prompt={'version':'6.8','superhuman_core_version':core.get('version','1.0'),'symbol':sym,'format':fmt,'narrative_engine':narrative,'creator_archetype':archetype,'authoritative_context':ctx,'agent_strategy':strategy,'original_research':research,'primary_story':story,'selected_opportunity':selected,'fresh_news':news_context,'research_notes_loaded':bool(research_notes),'instruction':f'''You are the senior editorial intelligence system for a world-class Binance Square creator. The frozen opportunity and bounded multi-agent council are authoritative. The goal is EARLY, useful discovery: identify an asset while its setup is forming, not after an obvious pump/breakout.\n\nAGENT COUNCIL:\n{json.dumps(strategy.get("agent_council") or {},ensure_ascii=False)}\n\nAGENT STRATEGY:\n{json.dumps(strategy,ensure_ascii=False)}\n\nFIRST: reason privately about 5 genuinely different theses. Prefer the earliest evidence-backed information advantage: capital-flow proxy, volume acceleration, relative strength, OI/funding, liquidity/order-book imbalance, volatility compression, structure, catalyst or anomaly. Distinguish an early candidate from an already-extended move.\n\nFOR PREDICTION/SETUP LANES: when supplied evidence contains a conditional trade setup, publish it as a scenario map with direction, trigger/confirmation, invalidation/SL, TP1 and TP2 and confidence. These are conditional levels, never guarantees. If no trustworthy setup is supplied, do not invent one; use a watch/confirmation thesis instead.\n\nOUTPUT: create 5 genuinely different finished candidates, not five rewrites: early-discovery thesis; data/mechanism thesis; contrarian/failure thesis; risk/confirmation thesis; concise high-energy thesis. Select the strongest.\n\nCONTENT STANDARD: specific asset hook; 1-3 strongest supplied facts; why-now mechanism; concrete trigger/confirmation; invalidation; scenario targets only when supplied; meaningful counterpoint; exactly ONE specific question.\n\nHUMAN QUALITY: natural rhythm, varied sentences, precise verbs, clear POV. No generic market-check filler, emoji stacks, fake personal experience, fake trades, fake outcomes or invented facts.\n\nEVIDENCE: use only supplied verified evidence. Never invent price, volume, OI, funding, whale activity, catalyst, target, SL, source or outcome.\n\nORIGINALITY: if the ticker can be swapped and the post still works, fail it. Headline-only summaries fail.\n\nVISUAL: specify what the TradingView/chart visual proves: trigger, structure, support/resistance or failure point.\n\nQUESTION: exactly one story-specific question at the end; no generic CTA.\n\nIf evidence is insufficient, return WAIT rather than forcing a post.''','selection_criteria':['early_signal_strength','information_advantage','mechanism','capital_flow','volume_acceleration','relative_strength','derivatives_confirmation','liquidity','volatility_compression','trigger_quality','invalidation_quality','target_quality','evidence_density','originality','reader_value','conversation_quality','human_voice','visual_information_value','risk_discipline'],'hook_candidates':hooks}
    p['agent_strategy']=strategy;p['candidate_generation_4']=prompt;PREFLIGHT.write_text(json.dumps(p,indent=2,ensure_ascii=False),encoding='utf-8');print(json.dumps({'status':'OK','version':'6.8','research':'refreshed','agent_strategy':'bound','agent_bridge':'applied','prediction_ready':bool(strategy.get('prediction_ready')),'information_advantage':research.get('information_advantage_score'),'format':fmt,'symbol':sym,'candidate_count':5},indent=2))
